/**
 * The typed IPC client. This is the *only* place the frontend talks to Rust.
 *
 * Payload types come from `src/bindings/`, which is generated by ts-rs from the
 * Rust models — never hand-edited. The thin wrappers below exist so command
 * names appear exactly once in the frontend; `scripts/check-ipc.mjs` asserts
 * that every `#[tauri::command]` in Rust has a wrapper here and vice versa, so
 * a renamed or removed command fails CI instead of failing at runtime.
 */
import { invoke } from "@tauri-apps/api/core";

import type { AppInfo } from "./bindings/AppInfo";
import type { CurveResult } from "./bindings/CurveResult";
import type { DetectedDevice } from "./bindings/DetectedDevice";
import type { DeviceStatus } from "./bindings/DeviceStatus";
import type { LengthUnit } from "./bindings/LengthUnit";
import type { MonitorInfo } from "./bindings/MonitorInfo";
import type { ParsedLength } from "./bindings/ParsedLength";
import type { IpcError } from "./bindings/IpcError";

export type {
  AppInfo,
  CurveResult,
  DetectedDevice,
  DeviceStatus,
  IpcError,
  LengthUnit,
  MonitorInfo,
  ParsedLength,
};

export const appInfo = () => invoke<AppInfo>("app_info");

export const listMonitors = () => invoke<MonitorInfo[]>("list_monitors");

export const listDevices = () => invoke<DetectedDevice[]>("list_devices");

export const parseLength = (input: string, unit: LengthUnit) =>
  invoke<ParsedLength>("parse_length", { input, unit });

export const solveCurvature = (args: {
  arcOrChordMm: number;
  radiusMm: number | null;
  measuredAsChord: boolean;
  eyeDistanceMm: number;
}) => invoke<CurveResult>("solve_curvature", args);

/**
 * Tauri rejects with whatever the command's error type serialised to. Ours is
 * always an IpcError, but a panic or a missing command yields a bare string, so
 * narrow rather than assume.
 */
export function asIpcError(e: unknown): IpcError {
  if (typeof e === "object" && e !== null && "kind" in e && "message" in e) {
    return e as IpcError;
  }
  return { kind: "unknown", message: String(e), remedy: null };
}
